BEGIN; CREATE TEMP TABLE measured ("id" uuid DEFAULT uuidv7() NOT NULL,"tenant_id" uuid NOT NULL,"user_id" uuid NOT NULL,"code_hash" character varying(255) NOT NULL,"used_at" timestamp with time zone,"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL);CREATE INDEX measured_index_0 ON measured USING btree (tenant_id, user_id) WHERE (used_at IS NULL);CREATE UNIQUE INDEX measured_index_1 ON measured USING btree (id);INSERT INTO measured(tenant_id,user_id,code_hash) SELECT '00000000-0000-0000-0000-000000000001',md5('user-'||i)::uuid,repeat('x',97) FROM generate_series(1,10000) n(i); SELECT json_build_object('rows',count(*),'avg_tuple_bytes',avg(pg_column_size(d)),'heap_bytes',pg_table_size('measured'),'index_bytes',pg_indexes_size('measured'),'total_bytes',pg_total_relation_size('measured'),'dropped_slots',(SELECT count(*) FROM pg_attribute WHERE attrelid='measured'::regclass AND attnum>0 AND attisdropped)) FROM measured d; ROLLBACK;